 "content": "from collections import deque


def transform(grid):
    """Remove each 4-connected nonzero component containing exactly two 9s."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    seen = set()

    for r in range(h):
        for c in range(w):
            if out[r][c] == 0 or (r, c) in seen:
                continue

            queue = deque([(r, c)])
            seen.add((r, c))
            cells = []
            nines = 0
            while queue:
                y, x = queue.popleft()
                cells.append((y, x))
                if out[y][x] == 9:
                    nines += 1
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= yy < h and 0 <= xx < w and out[yy][xx] != 0
                            and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        queue.append((yy, xx))

            if nines == 2:
                for y, x in cells:
                    out[y][x] = 0

    return out
